#!/usr/bin/env Rscript
options(stringsAsFactors=FALSE)
req <- c('Matrix','edgeR','limma','msigdbr')
miss <- req[!vapply(req, requireNamespace, logical(1), quietly=TRUE)]
if(length(miss)) stop('Missing packages: ', paste(miss,collapse=', '))
suppressPackageStartupMessages({library(Matrix);library(edgeR);library(limma);library(msigdbr)})
root <- normalizePath('.', winslash='/', mustWork=TRUE); out <- file.path(root,'results'); dir.create(out,FALSE,TRUE)
ddir <- file.path(root,'data','GSE218316')
cf <- file.path(ddir,'counts_annotated.rds'); mf <- file.path(ddir,'metadata_checked.rds'); gf <- file.path(ddir,'gene_annotation.rds')
gc <- c(file.path(root,'GSE218316_Hallmark_GSEA_Verified.rds'),file.path(out,'GSE218316_Hallmark_GSEA_Verified.rds')); gr <- gc[file.exists(gc)][1]
if(any(!file.exists(c(cf,mf,gf))) || is.na(gr)) stop('Required input file missing. Run from ~/Desktop/RNA3.0/RNA3 and verify data/GSE218316 plus GSEA RDS.')
counts<-readRDS(cf); meta<-as.data.frame(readRDS(mf)); ga<-as.data.frame(readRDS(gf)); saved<-readRDS(gr)
pick<-function(d,x,label,required=TRUE){n<-names(d); h<-x[tolower(x)%in%tolower(n)]; if(length(h)){return(n[match(tolower(h[1]),tolower(n))])}; if(required)stop('Cannot identify ',label,' column. Columns: ',paste(n,collapse=', ')); NULL}
cc<-pick(meta,c('Celltype','celltype','cell_type','CellType'),'cell type'); co<-pick(meta,c('Condition','condition','Treatment','treatment','group'),'condition'); dc<-pick(meta,c('Donor','donor','donor_id','DonorID'),'donor'); tc<-pick(meta,c('Timepoint','timepoint','time_point','Time','time','duration'),'timepoint'); idc<-pick(meta,c('cell','cell_id','CellID','barcode','Barcode'),'cell ID',FALSE)
if(is.null(idc)) stop('No usable metadata cell ID column found'); meta_ids<-as.character(meta[[idc]]); if(anyNA(meta_ids)||any(!nzchar(meta_ids))) stop('Missing/empty metadata cell IDs'); if(anyDuplicated(meta_ids)) stop('Duplicated metadata cell IDs'); rownames(meta)<-meta_ids; cat('Using metadata cell IDs from: ',idc,'\n',sep='')
if(sum(rownames(counts)%in%rownames(meta))>sum(colnames(counts)%in%rownames(meta))) counts<-Matrix::t(counts)
cm<-intersect(colnames(counts),rownames(meta)); if(!length(cm))stop('No matching cell IDs'); counts<-counts[,cm,drop=FALSE];meta<-meta[cm,,drop=FALSE]
cv<-tolower(trimws(meta[[cc]])); qv<-tolower(trimws(meta[[co]])); dv<-toupper(trimws(meta[[dc]])); tv<-tolower(trimws(as.character(meta[[tc]])))
keep<-(grepl('alpha',cv)|grepl('beta',cv))&(grepl('h2o2|hydrogen peroxide|peroxide',qv)|grepl('untreated|control|ctrl|vehicle|baseline',qv))&grepl('(^|[^0-9])24([^0-9]|$)',tv)&dv%in%c('D1','D2','D3')
meta<-meta[keep,,drop=FALSE];counts<-counts[,rownames(meta),drop=FALSE]
meta$Celltype_analysis<-ifelse(grepl('alpha',tolower(meta[[cc]])),'Alpha','Beta');meta$Condition_analysis<-ifelse(grepl('h2o2|hydrogen peroxide|peroxide',tolower(meta[[co]])),'H2O2','Untreated');meta$Donor_analysis<-toupper(trimws(meta[[dc]]));meta$Sample<-paste(meta$Donor_analysis,meta$Celltype_analysis,meta$Condition_analysis,sep='_')
cat('Selected cells:',ncol(counts),' Alpha:',sum(meta$Celltype_analysis=='Alpha'),' Beta:',sum(meta$Celltype_analysis=='Beta'),'\n'); if(ncol(counts)!=1618)warning('Expected 1618 cells; verify subset labels.')
mm<-Matrix::sparse.model.matrix(~0+factor(meta$Sample,levels=unique(meta$Sample)));colnames(mm)<-unique(meta$Sample);pb<-counts%*%mm
sm<-unique(meta[,c('Sample','Donor_analysis','Celltype_analysis','Condition_analysis')]);rownames(sm)<-sm$Sample;sm<-sm[colnames(pb),,drop=FALSE];cat('Pseudobulk samples:',ncol(pb),'\n');if(ncol(pb)!=12)warning('Expected 12 pseudobulk samples.')
sc<-pick(ga,c('gene_symbol','GeneSymbol','symbol','Symbol','gene_name','external_gene_name','hgnc_symbol'),'gene symbol');fc<-pick(ga,c('gene_id','GeneID','feature_id','ensembl_gene_id','ensembl','ID'),'feature ID',FALSE)
if(!is.null(fc)){mp<-setNames(as.character(ga[[sc]]),as.character(ga[[fc]]));symbols<-unname(mp[rownames(pb)])}else if(!is.null(rownames(ga))&&all(rownames(pb)%in%rownames(ga))) symbols<-as.character(ga[rownames(pb),sc]) else if(nrow(ga)==nrow(pb)) symbols<-as.character(ga[[sc]]) else stop('Cannot map features to symbols')
msig<-tryCatch(msigdbr::msigdbr(species='Homo sapiens',collection='H'),error=function(e)msigdbr::msigdbr(species='Homo sapiens',category='H')); gsn<-pick(msig,c('gs_name'),'gene set');gsy<-pick(msig,c('gene_symbol','human_gene_symbol'),'MSigDB symbol');sets<-lapply(split(as.character(msig[[gsy]]),as.character(msig[[gsn]])),unique)
sel9<-c('HALLMARK_HYPOXIA','HALLMARK_GLYCOLYSIS','HALLMARK_TNFA_SIGNALING_VIA_NFKB','HALLMARK_REACTIVE_OXYGEN_SPECIES_PATHWAY','HALLMARK_MTORC1_SIGNALING','HALLMARK_P53_PATHWAY','HALLMARK_APOPTOSIS','HALLMARK_UNFOLDED_PROTEIN_RESPONSE','HALLMARK_OXIDATIVE_PHOSPHORYLATION')
run_cam<-function(ct){j<-which(sm$Celltype_analysis==ct); s<-sm[j,,drop=FALSE];s$Donor<-factor(s$Donor_analysis);s$Condition<-factor(s$Condition_analysis,levels=c('Untreated','H2O2'));des<-model.matrix(~Donor+Condition,s);k<-which(colnames(des)=='ConditionH2O2');y0<-DGEList(pb[,j,drop=FALSE]);kg<-filterByExpr(y0,design=des);y0<-y0[kg,,keep.lib.sizes=FALSE];sy<-symbols[kg];good<-!is.na(sy)&nzchar(sy);y0<-y0[good,,keep.lib.sizes=FALSE];sy<-sy[good];y0<-calcNormFactors(y0);av<-rowMeans(cpm(y0,log=TRUE,prior.count=2));ord<-order(sy,-av);ch<-ord[!duplicated(sy[ord])];y<-y0[ch,,keep.lib.sizes=FALSE];sy<-sy[ch];rownames(y$counts)<-sy;y<-calcNormFactors(y);y<-estimateDisp(y,des,robust=TRUE);ind<-lapply(sets,function(z)which(sy%in%z));ind<-ind[vapply(ind,length,integer(1))>=15];ca<-limma::camera(y,index=ind,design=des,contrast=k,sort=FALSE);ca$Pathway<-rownames(ca);rownames(ca)<-NULL;ca$FDR<-p.adjust(ca$PValue,'BH');ca$Celltype<-ct;ca<-ca[,c('Celltype','Pathway',setdiff(names(ca),c('Celltype','Pathway')))];attr(ca,'ng')<-nrow(y);attr(ca,'dup')<-nrow(y0)-nrow(y);ca}
a<-run_cam('Alpha');b<-run_cam('Beta');cam<-rbind(a,b);write.csv(cam,file.path(out,'Table_S_CAMERA_ALL_Hallmark.csv'),row.names=FALSE);cs<-cam[cam$Pathway%in%sel9,,drop=FALSE];write.csv(cs,file.path(out,'Table_S_CAMERA_Selected9_Sensitivity.csv'),row.names=FALSE)
getg<-function(key){if(key%in%names(saved))return(as.data.frame(saved[[key]]));i<-which(tolower(names(saved))==tolower(key));if(length(i))return(as.data.frame(saved[[i[1]]]));stop('Missing ',key,' in GSEA RDS')};flatten_lists<-function(x){for(nm in names(x)){if(is.list(x[[nm]])){x[[nm]]<-vapply(x[[nm]],function(z){if(is.null(z)||length(z)==0)return('');paste(as.character(z),collapse=';')},character(1))}};x};std<-function(x,ct){p<-pick(x,c('pathway','Pathway','gs_name','term','Term'),'fgsea pathway');names(x)[names(x)==p]<-'Pathway';x$Celltype<-ct;x<-x[,c('Celltype','Pathway',setdiff(names(x),c('Celltype','Pathway')))];flatten_lists(x)};ag<-std(getg('alpha_gsea'),'Alpha');bg<-std(getg('beta_gsea'),'Beta');write.csv(ag,file.path(out,'Table_S_Hallmark_fgsea_ALL_Alpha.csv'),row.names=FALSE);write.csv(bg,file.path(out,'Table_S_Hallmark_fgsea_ALL_Beta.csv'),row.names=FALSE);fg<-rbind(ag,bg);write.csv(fg,file.path(out,'Table_S_Hallmark_fgsea_ALL_Combined.csv'),row.names=FALSE)
nc<-pick(fg,c('NES','nes'),'NES');pc<-pick(fg,c('padj','FDR','fdr','adj.P.Val'),'fgsea FDR');f9<-fg[fg$Pathway%in%sel9,c('Celltype','Pathway',nc,pc)];names(f9)[3:4]<-c('FGSEA_NES','FGSEA_FDR');names(cs)[names(cs)=='NGenes']<-'CAMERA_NGenes';names(cs)[names(cs)=='Direction']<-'CAMERA_Direction';names(cs)[names(cs)=='PValue']<-'CAMERA_PValue';names(cs)[names(cs)=='FDR']<-'CAMERA_FDR';cmp<-merge(f9,cs,by=c('Celltype','Pathway'),all=TRUE,sort=FALSE);cmp$FGSEA_significant<-!is.na(cmp$FGSEA_FDR)&cmp$FGSEA_FDR<.05;cmp$CAMERA_significant<-!is.na(cmp$CAMERA_FDR)&cmp$CAMERA_FDR<.05;sg<-ifelse(cmp$CAMERA_Direction=='Up',1,ifelse(cmp$CAMERA_Direction=='Down',-1,NA));cmp$Direction_concordant<-ifelse(is.na(cmp$FGSEA_NES)|is.na(sg),NA,sign(cmp$FGSEA_NES)==sg);write.csv(cmp,file.path(out,'Table_S_FGSEA_vs_CAMERA_Selected9.csv'),row.names=FALSE)
dbv<-if('db_version'%in%names(msig))paste(unique(na.omit(msig$db_version)),collapse=', ')else NA; sf<-file.path(out,'CAMERA_Sensitivity_sessionInfo.txt');sink(sf);cat('Generated: ',format(Sys.time()),'\n');cat('msigdbr version: ',as.character(packageVersion('msigdbr')),'\nMSigDB release: ',dbv,'\nedgeR: ',as.character(packageVersion('edgeR')),'\nlimma: ',as.character(packageVersion('limma')),'\n');cat('Design: ~ Donor + Condition separately within cell type\nBH FDR across all tested Hallmark sets\n');cat('Alpha genes after dedup: ',attr(a,'ng'),' duplicates removed: ',attr(a,'dup'),'\nBeta genes after dedup: ',attr(b,'ng'),' duplicates removed: ',attr(b,'dup'),'\n\n');print(sessionInfo());sink()
cat('\nDONE. Outputs written to:',out,'\n')
for(x in c('Table_S_Hallmark_fgsea_ALL_Combined.csv','Table_S_CAMERA_Selected9_Sensitivity.csv','Table_S_CAMERA_ALL_Hallmark.csv','Table_S_FGSEA_vs_CAMERA_Selected9.csv','CAMERA_Sensitivity_sessionInfo.txt'))cat(' - ',x,'\n',sep='')
